local GardenSecateursMaker = {}
local PRODUCTS = {
    iron_gardensecateurs = { name = "Železni vrtni škarjici", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtni škarjici za vrtnarje." },
    bronze_gardensecateurs = { name = "Bronast vrtni škarjici", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtni škarjici za vrtnarje." },
    silver_gardensecateurs = { name = "Srebrn vrtni škarjici", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtni škarjici za vrtnarje." },
    gilded_gardensecateurs = { name = "Pozlačen vrtni škarjici", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtni škarjici za vrtnarje." },
    jewel_set_gardensecateurs = { name = "Draguljast vrtni škarjici", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtni škarjici za vrtnarje." },
    royal_sovereign_gardensecateurs = { name = "Kraljevski suveren vrtni škarjici", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtni škarjici z biseri za krono." },
}
